def add_group_memberships(apps, schema_editor):
    """Everyone who has a calendar through a group gets a membership of it, as the app keeps them from now on:
    without a role of its own (their groups' applies), at the end of their sidebar."""
    CalendarGroup = apps.get_model("core", "CalendarGroup")
    CalendarMember = apps.get_model("core", "CalendarMember")
    Folder = apps.get_model("core", "Folder")
    User = apps.get_model("core", "User")

    shared = {
        (user_id, link.calendar_id)
        for link in CalendarGroup.objects.all()
        for user_id in User.objects.filter(groups=link.group_id).values_list("pk", flat=True)
    }

    next_position = {}
    for user_id, calendar_id in sorted(shared):
        if CalendarMember.objects.filter(user_id=user_id, calendar_id=calendar_id).exists():
            continue  # a direct membership wins
        if user_id not in next_position:
            tops = [
                CalendarMember.objects.filter(user_id=user_id, folder=None).aggregate(top=Max("position"))["top"],
                Folder.objects.filter(user_id=user_id, parent=None).aggregate(top=Max("position"))["top"],
            ]
            next_position[user_id] = max((t for t in tops if t is not None), default=-1) + 1
        CalendarMember.objects.create(
            user_id=user_id, calendar_id=calendar_id, role=None, source="group", position=next_position[user_id]
        )
        next_position[user_id] += 1


def remove_derived_memberships(apps, schema_editor):
    """Back to only granted memberships: the others would otherwise pass for granted ones."""
    apps.get_model("core", "CalendarMember").objects.exclude(source="direct").delete()


